import test from 'node:test';import assert from 'node:assert/strict';import {mkdtemp,rm,readFile,writeFile} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';
import { FederationEvaluationStore } from '../src/evals/federation-eval-store.mjs';import { evaluateFederatedProvider } from '../src/evals/federation-evaluator.mjs';import { createPrincipal } from '../src/core/principals.mjs';
const evaluator=createPrincipal({id:'eval-service',type:'service',roles:['federation-evaluator'],scopes:['evaluate'],trustDomain:'forgeos'});
test('federation evaluation receipts can only be persisted by trusted evaluator and tampering is detected',async()=>{const root=await mkdtemp(path.join(tmpdir(),'fed-eval-'));const store=new FederationEvaluationStore(root);await store.initialize();const provider={providerId:'p',providerDigest:'a'.repeat(64),capabilityId:'c',observedAt:new Date().toISOString(),trust:{blockers:[]}};const receipt=evaluateFederatedProvider({provider,capability:{capabilityId:'c'},scanReceipt:{status:'pass',providerDigest:provider.providerDigest},baseline:{passRate:.7,quality:70,tokens:1000},candidate:{passRate:.8,quality:80,tokens:1000}});await assert.rejects(()=>store.record(receipt,{principal:createPrincipal({id:'agent',type:'agent',roles:['federation-evaluator'],scopes:['evaluate']})}),/service principal/i);const stored=await store.record(receipt,{principal:evaluator});assert.equal((await store.get(stored.receiptSha256)).status,'pass');const file=path.join(root,'federation-evaluations.json');const state=JSON.parse(await readFile(file,'utf8'));state.receipts[0].status='fail';await writeFile(file,JSON.stringify(state));await assert.rejects(()=>store.get(stored.receiptSha256),/integrity/i);await rm(root,{recursive:true,force:true});});
